update dms_medicine_item_record set current_num = 0
where id in #{id}
  and (status is null or status <> 2) and COALESCE(current_num, 0) > 0

update dms_medicine_item_record set refund_num = COALESCE(num, 0), current_num = 0, status = 2
where id in #{id}
  and (status is null or status <> 2)
